  if(revision!==undefined&&revision!==null){validateRevision(handoff,revision);return new Map(revision.assignments.map(row=>[row.rowId,row]));}
  return new Map(handoff.rows.map(row=>[row.rowId,defaultAssignment(row)]));
}
