    proof.network===terms.network&&proof.asset===terms.asset&&proof.payer===terms.from&&proof.recipient===terms.to&&
    proof.atomicAmount===record.amountAtomic&&SHA.test(proof.transaction??'')&&proof.matchingTransfers===1&&
